diff --git a/repro/check.js b/repro/check.js
new file mode 100644
index 000000000..f3e98ea3e
--- /dev/null
+++ b/repro/check.js
@@ -0,0 +1,16 @@
+// Usage: node check.js <path/to/typescript.js> <file.ts>
+const path = require("path");
+const ts = require(path.resolve(process.argv[2]));
+const file = path.resolve(process.argv[3]);
+const program = ts.createProgram([file], { strict: true, noEmit: true });
+const checker = program.getTypeChecker();
+const sf = program.getSourceFile(file);
+let alias;
+sf.forEachChild(n => { if (ts.isTypeAliasDeclaration(n) && n.name.text === "Test") alias = n; });
+const t = checker.getTypeAtLocation(alias.name);
+const actual = checker.typeToString(t, undefined, ts.TypeFormatFlags.NoTruncation | ts.TypeFormatFlags.InTypeAlias);
+const expected = '{ prop1: "hello"; }';
+console.log("ts " + ts.version);
+console.log("Test =", actual);
+if (actual !== expected) { console.error(`FAIL: expected ${expected}`); process.exit(1); }
+console.log("OK");
diff --git a/repro/t.ts b/repro/t.ts
new file mode 100644
index 000000000..7c28a519a
--- /dev/null
+++ b/repro/t.ts
@@ -0,0 +1,21 @@
+type Wrapper<T> = {
+    _type: T
+}
+
+function stringWrapper(): Wrapper<string> {
+    return { _type: "" }
+}
+
+function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T> {
+    return { _type: obj }
+}
+
+const value = objWrapper({
+    prop1: stringWrapper() as Wrapper<"hello">
+})
+
+type Unwrap<T extends Wrapper<any>> = T['_type'] extends Record<string, Wrapper<any>> 
+    ? { [Key in keyof T['_type']]: Unwrap<T['_type'][Key]> } 
+    : T['_type']
+
+type Test = Unwrap<typeof value>
